using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Mbb.Archive.Modules.Search.Infrastructure.Persistence.Outbox;
namespace Mbb.Archive.Modules.Search.Infrastructure.Persistence.Configurations;
internal sealed class OutboxMessageConfiguration:IEntityTypeConfiguration<OutboxMessage>{public void Configure(EntityTypeBuilder<OutboxMessage>b){b.ToTable("outbox_messages",SearchSchema.Name);b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.EventName).HasColumnName("event_name").HasMaxLength(200);b.Property(x=>x.Payload).HasColumnName("payload").HasColumnType("jsonb");b.Property(x=>x.OccurredAt).HasColumnName("occurred_at");b.Property(x=>x.NextAttemptAt).HasColumnName("next_attempt_at");b.Property(x=>x.ProcessedAt).HasColumnName("processed_at");b.Property(x=>x.DeadLetteredAt).HasColumnName("dead_lettered_at");b.Property(x=>x.AttemptCount).HasColumnName("attempt_count");b.Property(x=>x.LastError).HasColumnName("last_error").HasMaxLength(4000);b.Property(x=>x.LockedBy).HasColumnName("locked_by").HasMaxLength(200);b.Property(x=>x.LockedUntil).HasColumnName("locked_until");b.HasIndex(x=>new{x.ProcessedAt,x.DeadLetteredAt,x.NextAttemptAt}).HasDatabaseName("ix_search_outbox_dispatch");}}
